#!/bin/bash

# Deploy Backend to Render - Automated Script
# This script prepares everything you need to deploy

set -e

echo "🚀 Render Backend Deployment Helper"
echo "=================================="
echo ""

# Colors
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m' # No Color

# Get API keys from .env
BACKEND_DIR="$(cd "$(dirname "$0")/backend" && pwd)"
ENV_FILE="$BACKEND_DIR/.env"

if [ ! -f "$ENV_FILE" ]; then
    echo "❌ Error: backend/.env file not found"
    exit 1
fi

echo "📋 Reading configuration from backend/.env..."
echo ""

# Extract API keys
ANTHROPIC_KEY=$(grep "^ANTHROPIC_API_KEY=" "$ENV_FILE" | cut -d'=' -f2- | tr -d '"' | tr -d "'")
OPENAI_KEY=$(grep "^OPENAI_API_KEY=" "$ENV_FILE" | cut -d'=' -f2- | tr -d '"' | tr -d "'")

if [ -z "$ANTHROPIC_KEY" ] || [ -z "$OPENAI_KEY" ]; then
    echo "❌ Error: API keys not found in backend/.env"
    exit 1
fi

# Generate secrets
echo "🔐 Generating secrets..."
SESSION_SECRET=$(openssl rand -base64 32)
JWT_SECRET=$(openssl rand -base64 32)

echo ""
echo "✅ Configuration ready!"
